import { createWorkspace, teardownWorkspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { readFileSync } from "fs";

// Step 1: Read trial ID and construct normalized workspace name
const trialId = readFileSync("/logs/artifacts/trial_id", "utf-8").trim();
const normalizedTrialId = trialId.toLowerCase().replace(/[^a-z0-9.-]/g, "-");
const workspaceName = `harbor-scoped-${normalizedTrialId}`;

async function main() {
  // Step 2: Provision workspace with scoped Editor credentials
  const result = await createWorkspace(workspaceName, {
    credentials: { role: "Editor" },
  });

  if (result.error) {
    throw new Error(`Failed to create workspace: ${result.error.message}`);
  }

  const workspace = result.data;

  // Step 3: Validate bucket and scoped credentials are present
  if (!workspace.bucket) {
    throw new Error("Workspace creation succeeded but bucket name is missing");
  }
  if (!workspace.credentials?.accessKeyId || !workspace.credentials?.secretAccessKey) {
    throw new Error(
      "Workspace creation succeeded but scoped credentials are missing — IAM key creation may have failed"
    );
  }

  try {
    // Step 4: Build S3 client using ONLY the scoped workspace credentials
    const s3 = new S3Client({
      region: "REDACTED",
      endpoint: "REDACTED",
      credentials: {
        accessKeyId: workspace.credentials.accessKeyId,
        secretAccessKey: workspace.credentials.secretAccessKey,
      },
    });

    // Step 5: Upload greeting.txt
    await s3.send(
      new PutObjectCommand({
        Bucket: workspace.bucket,
        Key: "greeting.txt",
        Body: "hello scoped",
      })
    );

    // Step 6: Report success
    console.log(`SCOPED_UPLOAD_OK ${workspace.bucket}`);
  } finally {
    // Step 7: Always tear down workspace (bucket + scoped key)
    await teardownWorkspace(workspace);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
